                    .build();
        } catch (ProductNotFoundException | InvalidPointAmountException | InsufficientPointsException e) {
            throw e;
        } catch (Exception e) {
            log.error("포인트 사용 중 예상치 못한 오류 발생 - 사용자: {}, 사용액: {}",
